  static Map<String, dynamic> getProgramData(String programName) {
    final all = allProgramsData;
    if (all.containsKey(programName)) {
      return all[programName] as Map<String, dynamic>;
    }
    // Fuzzy match
    for (final entry in all.entries) {
      if (entry.key.toLowerCase().contains(programName.toLowerCase()) ||
          programName.toLowerCase().contains(entry.key.toLowerCase())) {
        return entry.value as Map<String, dynamic>;
      }
    }
    // Default to premier program
    return all['Abbott Diabetes Care'] as Map<String, dynamic>;
  }
